const express = require('express');
const diagnostics_channel = require('diagnostics_channel');

const app = express();
const eventChannel = diagnostics_channel.channel('worker:task');

const eventRegistry = new Map();

eventChannel.subscribe((event) => {
  eventRegistry.set(event.eventId, {
    workerHost: event.hostname,
    queueName: event.queue,
    executionTimeMs: event.duration,
    tenantId: event.tenantId
  });
});

app.get('/diagnostics/events/:eventId', (req, res) => {
  if (!req.session || !req.session.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const event = eventRegistry.get(req.params.eventId);
  if (!event) {
    return res.status(404).json({ error: 'Event not found' });
  }

  // Enforce tenant scoping on diagnostics event
  if (event.tenantId !== req.session.tenantId) {
    return res.status(403).json({ error: 'Access denied: task event belongs to another tenant' });
  }

  res.json({
    eventId: req.params.eventId,
    workerHost: event.workerHost,
    queueName: event.queueName,
    executionTimeMs: event.executionTimeMs
  });
});

app.listen(8099);
